'use client'

import { useState } from 'react'
import { SportDetail, joinCoachingStaff, addEvent, addToRoster } from '../actions'
import SearchableSelect from '@/app/components/SearchableSelect' // Reuse your component!

export default function SportClient({ 
    sport, 
    currentUserId, 
    permissions 
}: { 
    sport: SportDetail, 
    currentUserId: string, 
    permissions: { isCoach: boolean, isFaculty: boolean } 
}) {
    const [activeTab, setActiveTab] = useState('roster')
    const [isSubmitting, setIsSubmitting] = useState(false)

    // Handlers for claiming coach, adding events, adding to roster...
    // (Implementation similar to RosterClient but specific to the sport context)

    return (
        <div>
            {/* Header */}
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900 dark:text-white">{sport.name}</h1>
                    <p className="text-gray-500">{sport.season} Season</p>
                </div>
                {!permissions.isCoach && permissions.isFaculty && (
                    <button onClick={() => joinCoachingStaff(sport.id)} className="bg-indigo-600 text-white px-4 py-2 rounded shadow hover:bg-indigo-700">
                        Claim as Coach
                    </button>
                )}
            </div>

            {/* Coaches List */}
            <div className="mb-8 p-4 bg-gray-50 dark:bg-gray-800 rounded-lg">
                <h3 className="font-bold text-sm uppercase text-gray-500 mb-2">Coaching Staff</h3>
                <div className="flex gap-4">
                    {sport.coaches.map(c => (
                        <div key={c.id} className="flex items-center gap-2">
                            <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-700 font-bold text-xs">
                                {c.name[0]}
                            </div>
                            <span className="text-sm font-medium dark:text-white">{c.name}</span>
                        </div>
                    ))}
                    {sport.coaches.length === 0 && <span className="text-sm text-gray-400 italic">No coaches assigned.</span>}
                </div>
            </div>

            {/* Tabs & Content */}
            {/* ... Roster Table with 'Add Cadet' search (using SearchableSelect) ... */}
            {/* ... Schedule List with 'Add Event' modal ... */}
        </div>
    )
}